DECLARE @ID_f570a210 UNIQUEIDENTIFIER,
@TemplateID_f570a210 UNIQUEIDENTIFIER,
@TypeID_f570a210 UNIQUEIDENTIFIER,
@TemplateText_f570a210 NVARCHAR(MAX),
@Priority_f570a210 INT,
@IsActive_f570a210 BIT
SET
  @ID_f570a210 = 'C3D4E5F6-A7B8-4C9D-0E1F-2A3B4C5D6E7F'
SET
  @TemplateID_f570a210 = 'F6A7B8C9-D0E1-4F2A-3B4C-5D6E7F809102'
SET
  @TypeID_f570a210 = 'E7AFCCEC-6A37-EF11-86D4-000D3A4E707E'
SET
  @TemplateText_f570a210 = N'You are a response-analysis assistant for MJ Forms. You are given the free-text answers a single respondent submitted to a form. Analyze EACH answer for quality and return the results as a single JSON object — no prose, no markdown fences, JSON only.

{% if FormContext %}The form is: "{{ FormContext }}". Judge each answer''s relevance and usefulness in that context.
{% endif %}
Here are the answers to analyze, in order:

{% for answer in Answers %}
Answer {{ loop.index }}:
- Question: {{ answer.questionPrompt }}
- Response: """{{ answer.text }}"""
{% endfor %}

Return a JSON object with an "answers" array containing EXACTLY one entry per answer above, in the SAME ORDER (entry 1 is for Answer 1, entry 2 for Answer 2, and so on). Do not add, drop, or reorder entries.

The JSON MUST match this shape exactly:
{
  "answers": [
    {
      "questionPrompt": string,   // echo the question this entry scores
      "score": number,            // integer 0-100: quality/usefulness of the response
      "rationale": string         // 1-2 sentences explaining the score
    }
  ]
}

Scoring guidance:
- Higher scores for specific, clear, on-topic, actionable answers; lower scores for vague, off-topic, or empty-of-content answers.
- Keep each rationale to 1-2 sentences.

Return ONLY the JSON object and nothing else.
'
SET
  @Priority_f570a210 = 100
SET
  @IsActive_f570a210 = 1
EXEC [${mjSchema}].spCreateTemplateContent @ID = @ID_f570a210,
  @TemplateID = @TemplateID_f570a210,
  @TypeID = @TypeID_f570a210,
  @TemplateText = @TemplateText_f570a210,
  @Priority = @Priority_f570a210,
  @IsActive = @IsActive_f570a210;

GO

